8	/// Which bearer value a call carries: the anon key (no user session exists
9	/// yet or is being replaced) or the stored access token (an existing
10	/// session's authenticated calls).
11	enum AuthMode { anonKey, userSession }
12	
13	/// The single way any feature calls the backend (FR-003, contracts/http-client.md).
14	/// Every `data/` layer depends on this, never on `dio` directly. Never throws
15	/// past this boundary — every dio exception is caught and mapped to a
16	/// [Failure] (FR-003 "never an unhandled crash").
17	class ApiClient {
