13	/// The single login/sign-up screen, toggled between modes by a text link
14	/// (FR-008). Blocks the network call and shows an inline validation message
15	/// for an empty field (Edge Cases: "no network call made").
16	class LoginSignupPage extends StatefulWidget {
17	  const LoginSignupPage({super.key, this.isReauth = false});
18	
19	  /// True when this screen was pushed on top of the "Sessão expirada"
20	  /// overlay (session_expired_overlay.dart) rather than reached from a fresh
21	  /// launch — on success, it pops back to the preserved screen underneath
22	  /// instead of pushing a new Home/Chat route (FR-013/FR-014, User Story 5).
23	  final bool isReauth;
24	
25	  @override
26	  State<LoginSignupPage> createState() => _LoginSignupPageState();
27	}
28	
29	class _LoginSignupPageState extends State<LoginSignupPage> {
30	  final _emailController = TextEditingController();
31	  final _passwordController = TextEditingController();
32	  String? _localValidationError;
33	  bool _showLoadingIndicator = false;
34	  Timer? _loadingIndicatorTimer;
35	
36	  @override
37	  void dispose() {
38	    _emailController.dispose();
39	    _passwordController.dispose();
40	    _loadingIndicatorTimer?.cancel();
41	    super.dispose();
42	  }
43	
44	  void _onSubmit(AuthFormMode mode) {
45	    final email = _emailController.text.trim();
46	    final password = _passwordController.text;
47	
48	    if (email.isEmpty || password.isEmpty) {
49	      setState(() => _localValidationError = 'Preencha e-mail e senha.');
50	      return;
51	    }
52	
53	    setState(() => _localValidationError = null);
54	    final bloc = context.read<AuthBloc>();
55	    bloc.add(
56	      mode == AuthFormMode.login
57	          ? LoginSubmitted(email: email, password: password)
58	          : SignUpSubmitted(email: email, password: password),
59	    );
60	  }
61	
62	  void _handleStatusChange(AuthStatus status) {
63	    _loadingIndicatorTimer?.cancel();
64	    if (status == AuthStatus.loading) {
65	      // RNF01: only show a loading indicator once the call exceeds 300 ms.
66	      _loadingIndicatorTimer = Timer(const Duration(milliseconds: 300), () {
67	        if (mounted) setState(() => _showLoadingIndicator = true);
68	      });
69	    } else {
70	      setState(() => _showLoadingIndicator = false);
71	    }
72	  }
73	
74	  String _messageFor(Failure failure) {
75	    return switch (failure) {
76	      AuthInvalidFailure() =>
77	        'E-mail ou senha inválidos, ou e-mail já cadastrado.',
78	      ValidationFailure() => 'Não foi possível enviar — revise os campos.',
79	      RateLimitedFailure() => 'Muitas tentativas — aguarde um instante.',
80	      NetworkTimeoutFailure() || NetworkOfflineFailure() =>
81	        'Sem conexão — toque para tentar novamente.',
82	      _ => failure.message,
83	    };
84	  }
85	
86	  @override
87	  Widget build(BuildContext context) {
88	    return Scaffold(
89	      backgroundColor: DesignTokens.colorSurfaceBg,
90	      body: SafeArea(
91	        child: BlocConsumer<AuthBloc, AuthState>(
92	          listenWhen: (previous, current) => previous.status != current.status,
93	          listener: (context, state) {
94	            _handleStatusChange(state.status);
95	            if (state.status == AuthStatus.authenticated) {
96	              if (widget.isReauth) {
97	                // Pop the pushed Login route and the dialog route beneath
98	                // it, landing back on the exact screen/state the overlay
99	                // was raised over (FR-013/FR-014).
100	                Navigator.of(context, rootNavigator: true)
101	                  ..pop()
102	                  ..pop();
103	              } else {
104	                // research.md R3: context.push, never go/replace, so the
105	                // login screen's State is never disposed underneath Home/Chat.
106	                context.push(AppRoutes.home);
107	              }
108	            }
109	          },
110	          builder: (context, state) {
111	            final isSignUp = state.formMode == AuthFormMode.signUp;
112	            final isLoading = state.status == AuthStatus.loading;
113	
114	            return SingleChildScrollView(
115	              padding: const EdgeInsets.all(DesignTokens.spacingLg),
116	              child: Column(
117	                crossAxisAlignment: CrossAxisAlignment.stretch,
118	                children: [
119	                  const SizedBox(height: DesignTokens.spacing2xl),
120	                  Text(
121	                    isSignUp ? 'Crie sua conta' : 'Bem-vindo de volta',
122	                    style: DesignTokens.textHeadlineMd,
123	                    textAlign: TextAlign.center,
124	                  ),
125	                  const SizedBox(height: DesignTokens.spacingXl),
126	                  TextField(
127	                    controller: _emailController,
128	                    keyboardType: TextInputType.emailAddress,
129	                    enabled: !isLoading,
130	                    decoration: const InputDecoration(labelText: 'E-mail'),
131	                  ),
132	                  const SizedBox(height: DesignTokens.spacingMd),
133	                  TextField(
134	                    controller: _passwordController,
135	                    obscureText: true,
136	                    enabled: !isLoading,
137	                    decoration: const InputDecoration(labelText: 'Senha'),
138	                  ),
139	                  if (_localValidationError != null) ...[
140	                    const SizedBox(height: DesignTokens.spacingSm),
141	                    Text(
142	                      _localValidationError!,
143	                      style: DesignTokens.textBodyMd.copyWith(
144	                        color: DesignTokens.colorError,
145	                      ),
146	                    ),
147	                  ],
148	                  if (state.status == AuthStatus.failure &&
149	                      state.failure != null) ...[
150	                    const SizedBox(height: DesignTokens.spacingSm),
151	                    Text(
152	                      _messageFor(state.failure!),
153	                      style: DesignTokens.textBodyMd.copyWith(
