    when(() => vaultRepository.setBiometricPreferenceLocally(true))
        .thenAnswer((_) async {});
    when(() => biometricsPreferenceRepository.save(true)).thenAnswer(
      (_) async => const Left(
        NetworkOfflineFailure(message: 'offline', requestId: 'r1'),
      ),
    );

