    super.initState();
    context.read<VaultBloc>().add(const VaultOpened());
  }

  void _useEmailPassword() => context.push(AppRoutes.login);

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: DesignTokens.colorSurfaceBg,
